<?php declare(strict_types=1);require_once __DIR__.'/_common.php';$id=(int)($_GET['id']??0);if(post()){verifyCsrf();$action=$_POST['action']??'';$id=(int)($_POST['id']??0);if($action==='delete'){db()->prepare('DELETE FROM team WHERE id=?')->execute([$id]);adminAudit('delete','team',$id);redirect('team.php');}$name=clean('full_name',150);$role=clean('role',100);$bio=clean('bio',3000);if($id){db()->prepare('UPDATE team SET full_name=?,role=?,bio=? WHERE id=?')->execute([$name,$role,$bio,$id]);adminAudit('update','team',$id);}else{db()->prepare('INSERT INTO team(full_name,role,bio) VALUES(?,?,?)')->execute([$name,$role,$bio]);adminAudit('create','team');}flash('success','Team member saved.');redirect('team.php');}$edit=null;if($id){$s=db()->prepare('SELECT * FROM team WHERE id=?');$s->execute([$id]);$edit=$s->fetch();}$rows=db()->query('SELECT * FROM team ORDER BY id DESC')->fetchAll();$pageTitle='Team';require dirname(__DIR__).'/includes/header.php';?><section class="section"><div class="container"><p class="eyebrow">Administration</p><h1 class="section-title">Team.</h1><div class="form-shell" style="max-width:none"><form method="post"><?=csrfField()?><input type="hidden" name="id" value="<?=$edit['id']??0?>"><input type="hidden" name="action" value="save"><div class="field"><label>Full name</label><input name="full_name" required value="<?=e($edit['full_name']??'')?>"></div><div class="field"><label>Role</label><input name="role" required value="<?=e($edit['role']??'')?>"></div><div class="field"><label>Bio</label><textarea name="bio"><?=e($edit['bio']??'')?></textarea></div><button class="btn primary">Save</button></form></div><div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['full_name'])?></td><td><?=e($r['role'])?></td><td><a class="btn ghost" href="team.php?id=<?=$r['id']?>">Edit</a> <form method="post" style="display:inline"><?=csrfField()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn coral" data-confirm="Delete this team member?">Delete</button></form></td></tr><?php endforeach;?></tbody></table></div></div></section><?php require dirname(__DIR__).'/includes/footer.php';
